css:
:root{--k:#080808;--k2:#111111;--w:#F7F7F5;--g:#F3F4F6;--l:#C7FF3F;--ink:#1a1a1a;--mute:#5f6368;--line:#e2e3e0;--dline:#26262a;--dmute:#a1a1a6;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
html{scroll-behavior:smooth;scroll-padding-top:80px}
*,*::before,*::after{box-sizing:inherit}
body{margin:0;font:400 16px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:var(--w);-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:Sora,Manrope,sans-serif;margin:0;line-height:1.12;letter-spacing:-.02em}
p{margin:0}a{color:inherit;text-decoration:none}
:focus-visible{outline:2px solid var(--l);outline-offset:3px;box-shadow:0 0 0 4px var(--k)}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
section{padding:88px 0}
.dark{background:var(--k);color:#fff}.dark2{background:var(--k2);color:#fff}.grey{background:var(--g)}
.dark p,.dark2 p{color:var(--dmute)}
.sh{max-width:640px;margin-bottom:44px}
.sh h2{font-size:clamp(28px,4vw,42px)}
.sh p{margin-top:14px;color:var(--mute);font-size:17px}
.dark .sh p,.dark2 .sh p{color:var(--dmute)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 22px;border-radius:999px;font:600 15px Inter;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s}
.btn:hover{transform:translateY(-2px)}
.b-l{background:var(--l);color:var(--k)}
.b-o{border-color:#ffffff40;color:#fff}.b-o:hover{background:#ffffff14}
.b-d{background:var(--k);color:#fff}
.b-w{border-color:#25D366;color:#25D366}.b-w:hover{background:#25D36618}
.ctas{display:flex;flex-wrap:wrap;gap:12px}
nav{position:sticky;top:0;z-index:20;background:#080808f2;color:#fff;border-bottom:1px solid var(--dline)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font:700 21px Sora;letter-spacing:-.03em}.logo i{font-style:normal;color:var(--l)}
nav ul{display:flex;gap:30px;list-style:none;margin:0;padding:0;font-size:14.5px;color:#d0d0d4}
nav ul a:hover,nav ul a.on{color:var(--l)}
nav .btn{padding:10px 18px;font-size:14px}
/* hero */
.hero{padding:72px 0 88px;overflow:hidden}
.hero .wrap{display:grid;grid-template-columns:1fr 1.15fr;gap:48px;align-items:center}
.lab{display:inline-flex;align-items:center;gap:10px;font:600 13px Inter;letter-spacing:.08em;color:var(--l);margin-bottom:22px}
.lab::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--l)}
.hero h1{font-size:clamp(34px,4.6vw,60px);line-height:1.04;letter-spacing:-.035em}
.hero .sub{margin:22px 0 32px;font-size:clamp(17px,2vw,19px);max-width:460px;color:#d6d6da}
.br{background:var(--k2);border:1px solid var(--dline);border-radius:16px;box-shadow:0 24px 50px #000a;overflow:hidden;position:relative}
.br .top{display:flex;align-items:center;gap:6px;padding:11px 14px;border-bottom:1px solid var(--dline)}
.br .top b{width:9px;height:9px;border-radius:50%;background:#333}
.br .url{margin-left:12px;flex:1;max-width:260px;font-size:12px;color:var(--dmute);background:#1a1a1e;border-radius:99px;padding:4px 14px}
.site{background:var(--w);color:var(--ink);padding:0 0 22px}
.sn{display:flex;justify-content:space-between;align-items:center;padding:14px 22px;font-size:12px;border-bottom:1px solid var(--line)}
.sn b{font:700 14px Sora}.sn span{color:var(--mute);margin-left:16px}.sn em{font-style:normal;background:var(--k);color:#fff;padding:6px 13px;border-radius:99px;font-weight:600}
.sh1{margin:22px;border-radius:14px;background:var(--k);color:#fff;padding:30px 26px;position:relative;min-height:170px}
.sh1 h3{font-size:24px;max-width:300px;letter-spacing:-.03em}.sh1 p{font-size:12.5px;color:#bbb;margin:10px 0 16px;max-width:280px}
.sh1 .pill{display:inline-block;padding:8px 16px;border-radius:99px;background:var(--l);color:var(--k);font:600 12px Inter}
.sh1 .art{position:absolute;right:22px;top:22px;bottom:22px;width:34%;border-radius:10px;background:linear-gradient(135deg,#2a2a2e,#17171a);border:1px solid #333}
.cr{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:0 22px}
.cr div{background:#fff;border:1px solid var(--line);border-radius:10px;padding:12px;font-size:11.5px;font-weight:600}
.cr i{display:block;height:34px;border-radius:6px;background:var(--g);margin-bottom:8px}
.chip{position:absolute;right:16px;bottom:16px;background:var(--k);border:1px solid var(--l);color:#fff;font-size:12px;padding:9px 14px;border-radius:99px;display:flex;gap:8px;align-items:center;box-shadow:0 10px 24px #0006}
.chip::before{content:"";width:8px;height:8px;border-radius:50%;background:#25D366}
.cap{margin-top:12px;font-size:13px;color:var(--dmute)}
/* problems */
.pr{border-top:1px solid var(--line)}
.pr .row{display:grid;grid-template-columns:.9fr 1.4fr;gap:32px;padding:26px 0;border-bottom:1px solid var(--line);align-items:start}
.pr h3{font-size:20px}.pr p{color:var(--mute);max-width:560px}.pr p b{color:var(--ink);font-weight:600}
/* bento */
.bento{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}
.bc{border-radius:22px;padding:30px;background:#fff;border:1px solid var(--line);position:relative;overflow:hidden}
.bc h3{font-size:21px;margin-bottom:10px}.bc p{color:var(--mute);max-width:420px;font-size:15.5px}
.bc ul{margin:16px 0 0;padding:0;list-style:none;display:flex;flex-wrap:wrap;gap:8px}
.bc li{font-size:13px;padding:6px 12px;border-radius:99px;background:var(--g)}
.s3{grid-column:span 3}.s4{grid-column:span 4}.s2{grid-column:span 2}
.bc.dk{background:var(--k);border-color:var(--k);color:#fff;min-height:260px}.bc.dk p{color:var(--dmute)}.bc.dk li{background:#1c1c20;color:#d8d8dc}
.bc .tag{display:inline-block;font:600 12px Inter;color:var(--k);background:var(--l);padding:5px 12px;border-radius:99px;margin-bottom:16px}
.dash{display:flex;gap:10px;margin-top:22px}
.dash b{flex:1;height:64px;border-radius:12px;border:1px solid var(--dline);background:#16161a}.dash b:first-child{border-color:var(--l)}
/* journey */
.jr{display:grid;grid-template-columns:1fr auto 1fr auto 1fr auto 1fr auto 1fr;gap:12px;align-items:stretch}
.jc{border:1px solid var(--dline);border-radius:18px;padding:24px 20px;background:var(--k2)}
.jc h3{font-size:19px;color:var(--l);margin-bottom:10px}.jc p{font-size:14.5px}
.arr{align-self:center;color:var(--l);font:600 22px Sora}
/* industries */
.ind{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.id{background:#fff;border:1px solid var(--line);border-radius:18px;padding:24px;transition:border-color .2s}
.id:hover{border-color:var(--k)}
.id h3{font-size:18px;margin-bottom:8px}.id p{font-size:14.5px;color:var(--mute)}
.id.more{background:var(--k);border-color:var(--k);color:#fff;display:flex;flex-direction:column;justify-content:space-between;gap:16px}.id.more p{color:var(--dmute)}
.id.more a{color:var(--l);font-weight:600;font-size:14.5px}
/* featured work */
.fw{display:grid;grid-template-columns:1.5fr 1fr;gap:40px;align-items:center}
.fw .br{box-shadow:0 24px 50px #0008}
.hs{background:var(--w);color:var(--ink)}
.hh{margin:0;min-height:230px;background:linear-gradient(160deg,#1b1b1f,#0c0c0e);color:#fff;padding:36px 30px;position:relative}
.hh h3{font-size:30px;max-width:340px;letter-spacing:-.03em}.hh p{font-size:13px;color:#bbb;margin:10px 0 18px;max-width:300px}
.bk{position:absolute;right:26px;bottom:-26px;left:26px;background:#fff;color:var(--ink);border-radius:14px;padding:14px 18px;display:grid;grid-template-columns:repeat(3,1fr) auto;gap:14px;font-size:11.5px;box-shadow:0 14px 30px #0004;align-items:center}
.bk span{color:var(--mute);display:block;font-size:10.5px}.bk b{font-weight:600}.bk em{font-style:normal;background:var(--l);color:var(--k);font-weight:600;padding:9px 16px;border-radius:99px}
.rms{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:52px 22px 24px}
.rms div{border:1px solid var(--line);border-radius:10px;padding:10px;font-size:11.5px;font-weight:600;background:#fff}.rms i{display:block;height:54px;border-radius:6px;background:var(--g);margin-bottom:8px}
.cp{position:absolute;top:14px;left:14px;z-index:2;font:600 11.5px Inter;padding:4px 11px;border-radius:99px;background:var(--l);color:var(--k)}
.fw h3{font-size:26px;margin:0 0 14px}.fw p{color:var(--mute);margin-bottom:16px}
.fw ul{margin:0 0 22px;padding:0;list-style:none}.fw li{padding:9px 0;border-top:1px solid var(--line);font-size:15px}
.fine{font-size:14px;color:var(--mute)}
/* tech */
.tk{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}
.tk div{border:1px solid var(--dline);border-radius:18px;padding:24px;background:var(--k)}
.tk h3{font-size:19px;color:var(--l);margin-bottom:8px}.tk p{font-size:14.5px}
.tnote{margin-top:24px;font-size:14px}
/* faq */
.faq{max-width:780px}
details{border-top:1px solid var(--line);padding:20px 0}details:last-child{border-bottom:1px solid var(--line)}
summary{cursor:pointer;font:600 18px Sora;list-style:none;display:flex;justify-content:space-between;gap:16px}
summary::-webkit-details-marker{display:none}summary::after{content:"+";font-size:24px;line-height:1;transition:transform .2s}
details[open] summary::after{transform:rotate(45deg)}
details p{margin-top:12px;color:var(--mute);max-width:640px}
/* cta */
.cta{background:var(--l);color:var(--k);padding:96px 0}
.cta h2{font-size:clamp(32px,5.6vw,64px);letter-spacing:-.035em;max-width:800px}
.cta p{margin:18px 0 32px;font-size:18px;max-width:520px;color:#2a3300}
/* footer */
footer{background:var(--k);color:#fff;padding:72px 0 32px}
.ft{display:grid;grid-template-columns:1.6fr repeat(3,1fr);gap:40px}
footer p,footer li,footer a{color:var(--dmute);font-size:14.5px}
footer h4{font-size:14px;margin-bottom:14px}
footer ul{list-style:none;margin:0;padding:0}footer li{padding:5px 0}footer a:hover{color:var(--l)}
.fb{margin-top:48px;padding-top:24px;border-top:1px solid var(--dline);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13.5px;color:var(--dmute)}
.big{font:700 clamp(40px,12vw,150px)/1 Sora;letter-spacing:-.05em;color:#161618;margin-top:40px;white-space:nowrap;overflow:hidden}
/* tablet 768 + below */
@media(max-width:1020px){
.hero .wrap,.fw{grid-template-columns:1fr}
.s3,.s4,.s2{grid-column:span 6}.bento .s2{grid-column:span 3}.bento .s4{grid-column:span 6}
.jr{grid-template-columns:1fr}.arr{transform:rotate(90deg);justify-self:center}
.ind{grid-template-columns:repeat(2,1fr)}.tk{grid-template-columns:repeat(2,1fr)}
.pr .row{grid-template-columns:1fr;gap:8px}.ft{grid-template-columns:1fr 1fr}}
@media(max-width:860px){nav ul{display:none}}
/* mobile 390 */
@media(max-width:600px){
section{padding:64px 0}.wrap{padding:0 20px}
.bento .s2,.bento .s3{grid-column:span 6}.bc{padding:24px}
.ind,.tk{grid-template-columns:1fr}.ctas .btn{width:100%;justify-content:center}
.sh1 .art{display:none}.cr{grid-template-columns:1fr 1fr}.cr div:last-child{display:none}
.bk{grid-template-columns:1fr 1fr;right:14px;left:14px}.bk em{grid-column:span 2;text-align:center}.hh{padding-bottom:92px}.rms{padding-top:100px}
.chip{display:none}.ft{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
